def _read_body(self, code, headers, delegate):
    # Normalize the header keys
    normalized_headers = {k.lower(): v for k, v in headers.items()}

    if "content-length" in normalized_headers:
        if "transfer-encoding" in normalized_headers:
            raise httputil.HTTPInputError(
                "Response with both Transfer-Encoding and Content-Length")
        if "," in normalized_headers["content-length"]:
            pieces = re.split(r',\s*', normalized_headers["content-length"])
            if any(i != pieces[0] for i in pieces):
                raise httputil.HTTPInputError(
                    "Multiple unequal Content-Lengths: %r" %
                    normalized_headers["content-length"])
            normalized_headers["content-length"] = pieces[0]

        try:
            content_length = int(normalized_headers["content-length"])
        except ValueError:
            raise httputil.HTTPInputError(
                "Only integer Content-Length is allowed: %s" % normalized_headers["content-length"])

        if content_length > self._max_body_size:
            raise httputil.HTTPInputError("Content-Length too long")
    else:
        content_length = None

    if code == 204:
        if ("transfer-encoding" in normalized_headers or
                content_length not in (None, 0)):
            raise httputil.HTTPInputError(
                "Response with code %d should not have body" % code)
        content_length = 0

    if content_length is not None:
        return self._read_fixed_body(content_length, delegate)
    if normalized_headers.get("transfer-encoding") == "chunked":
        return self._read_chunked_body(delegate)
    if self.is_client:
        return self._read_body_until_close(delegate)
    return None
